import{_ as a,o as r,c as e,aw as t}from"./chunks/framework.DLufY-ao.js";const p=JSON.parse('{"title":"Функциональное программирование","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/programming/fp/info.md","filePath":"wiki/dev-commit/theory/programming/fp/info.md"}'),l={name:"wiki/dev-commit/theory/programming/fp/info.md"};function o(n,i,c,s,d,m){return r(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="функциональное-программирование" tabindex="-1">Функциональное программирование <a class="header-anchor" href="#функциональное-программирование" aria-label="Permalink to &quot;Функциональное программирование&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p></div><ul><li><strong>Функциональное программирование</strong> - последовательный вызов набора функций</li><li>Процесс вычисления трактуется как вычисление значений функций в математическом понимании</li><li>Специфические возможности по работе с функциями: передача функций другим функциям в качестве аргументов и возврат функций из других функций</li><li>Предполагает обходиться вычислением результатов функций от исходных данных и результатов других функций</li><li>Описывает математические отношения между данными и целью</li><li>Один из видов декларативного программрования</li><li>Нужно что-то посчитать, но функция которая это считает возвращает не результат, а рецепт для вычисления результата, т.е. возвращает функцию, которая посчитает результат</li><li>Методы для функционального программирования в JavaScript: arr.map, arr.forEach, arr.filter, arr.sort, arr.concat, arr.join, arr.reduce, arr.reduceRight, Object.assign, Object.keys()</li></ul><h3 id="что-не-используется" tabindex="-1">Что не используется <a class="header-anchor" href="#что-не-используется" aria-label="Permalink to &quot;Что не используется&quot;">​</a></h3><ol><li>Хранение состояния (нет переменных и операторов присваивания)</li></ol><h3 id="принципы" tabindex="-1">Принципы <a class="header-anchor" href="#принципы" aria-label="Permalink to &quot;Принципы&quot;">​</a></h3><ol><li>При вызове функции с одними и теми же аргументами мы всегда получим одинаковый результат: выходные данные зависят только от входных</li><li>То, что в императивных языках делается путём присваивания значений переменным, в функциональных достигается путём передачи выражений в параметры функций</li><li>Не нужно описывать шаги, нужно определить функцию, выполнить функции последовательно и в результате выполнения набор функций будет получен результат</li><li>Разделение функций и данных</li></ol>',7)])])}const _=a(l,[["render",o]]);export{p as __pageData,_ as default};
